repl('B0717','对同一文档与种子，各结构修正对照固定T1、对应I0最终输出G0、候选快照、对象评分和合法化规则。I0保留该G0，其他结构修正配置从同一G0开始追加处理。RelationOnly固定组件，Sequential先后接受两层修改，Single在单对象动作中共同接受，SetLocal扩展集合动作，Global共同选择所有对象。690个主输入均小于2500变量，I1全部走Global；Single/SetLocal消融的适用范围与这一主路由分开报告。','明确同一G0是在同文档、同种子、同T1下固定；将同候选评分控制限定于结构修正，避免覆盖会重新生成候选的Regenerate。')

# Preserve every existing inline OMML object while editing adjacent prose.
normalized=[]
for p in patches:
 i=p['block_id']
 if i=='B0285':
  p.update(op='replace_text_fragment',old_text='则初始图按以下过程确定：',new_text='先选择重排序胜者，再执行共同合法化及继承的BR-O有界修正，形成完整I0的终态：',preserve_native_math=True)
 elif i=='B0287':
  p.update(op='replace_text_fragment',old_text=B[i]['text'].split('其变更需要记录。',1)[1],new_text=p['new_text'].split('其变更需要记录。',1)[1],preserve_native_math=True)
 elif i=='B0288':
  p.update(old_text='第四章在初始选择后固定跨度集合',new_text='第四章在获得I0终态G0后，构建并冻结跨度集合')
 elif i=='B0551':
  normalized.append(dict(block_id=i,op='replace_text_fragment',old_text='修正开始前构建固定跨度集合',new_text='追加修正开始前构建固定跨度集合',reason='在原生U数学对象之前补明阶段。',preserve_native_math=True))
  p.update(op='replace_text_fragment',old_text=B[i]['text'].split('U。',1)[1],new_text=p['new_text'].split('U。',1)[1].replace('包括BR-O在形成G0时保留下来的新跨度','包括BR-O可能引入并最终保留在G0中的新跨度'),preserve_native_math=True)
 elif i=='B0588':
  p.update(old_text='累计编辑量与最终图相对 ',new_text='这里只统计追加修正阶段，BR-O已有编辑另行记账；累计编辑量与最终图相对I0终态 ')
 elif i=='B0688':
  p.update(old_text='主配置',new_text='追加修正阶段的主配置')
 elif i=='B0689':
  p.update(old_text='经共同合法化、其对象受保护地留在候选宇宙中',new_text='为通过合法性复核的完整I0终态、其对象受保护地留在候选宇宙中')
 elif i=='B0961':
  p['new_text']=p['new_text'].replace('并以阶段标识关联Grank、Gpre和BR-O返回记录。','；快照还应以阶段标识关联Grank、Gpre和BR-O返回记录。')
 normalized.append(p)
patches=normalized

(ROOT/'_agents/protocol/patches.json').write_text(json.dumps(patches,ensure_ascii=False,indent=2)+'\n')
